{
  "name": "check_tx_pending",
  "confidence": "medium",
  "docstring": "If the state's TX-pending flag is set, locate or record the matching 12-byte descriptor slot, update the active slot indices, clear the descriptor fields, and acknowledge the flag; otherwise initialize the current RX packet descriptor.",
  "subsystem": "bt",
  "var_renames": {
    "a1": "tx_state",
    "v1": "flags",
    "v2": "tx_pending_bit",
    "v3": "state",
    "v4": "pending_count",
    "v5": "target_id",
    "v6": "slot",
    "v7": "slot_index",
    "v8": "last_slot",
    "v9": "descriptor_end",
    "v10": "descriptor_ptr",
    "v12": "descriptor_end",
    "v13": "slot_ptr"
  },
  "struct_hints": [
    {
      "offset": 166,
      "meaning": "byte state flags; bit 0x10 pending TX/service flag, bit 0x20 serviced/ack flag"
    },
    {
      "offset": 184,
      "meaning": "uint16 pending descriptor count or occupied slots"
    },
    {
      "offset": 190,
      "meaning": "uint16 target descriptor id/sequence to match in pending table"
    },
    {
      "offset": 136,
      "meaning": "uint16 current descriptor slot index; initialized to 0xFF when no slots are pending"
    },
    {
      "offset": 138,
      "meaning": "uint16 descriptor head/match index"
    },
    {
      "offset": 140,
      "meaning": "uint16 descriptor tail/current index"
    },
    {
      "offset": 154,
      "meaning": "byte flag cleared after a pending TX service path"
    },
    {
      "offset": 3068,
      "meaning": "uint16 auxiliary saved value; cleared when pending count is zero"
    },
    {
      "offset": 3070,
      "meaning": "uint16 last target id stored when pending count is zero"
    },
    {
      "offset": 4,
      "meaning": "start of 12-byte packet descriptor table; slot i is tx_state + 4 + 12*i"
    },
    {
      "offset": 6,
      "meaning": "first descriptor cleanup field; descriptor+2"
    },
    {
      "offset": 8,
      "meaning": "first descriptor fallback field zeroed; descriptor+4"
    },
    {
      "offset": 10,
      "meaning": "first descriptor key/id compared with target_id; descriptor+6"
    }
  ]
}
